package com.yanyuetong.utils;

import com.yanyuetong.entity.ReservationBatch;
import com.yanyuetong.enums.ReservationResultCode;
import com.yanyuetong.exception.BadRequestException;
import lombok.extern.slf4j.Slf4j;
import org.springframework.core.io.ClassPathResource;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.script.DefaultRedisScript;
import org.springframework.stereotype.Component;

import java.time.Duration;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.util.Arrays;

import static com.yanyuetong.utils.RedisConstants.RESERVATION_BATCH_QUOTA_KEY;
import static com.yanyuetong.utils.RedisConstants.RESERVATION_BATCH_QUOTA_TTL_BUFFER_HOURS;
import static com.yanyuetong.utils.RedisConstants.RESERVATION_BATCH_USERS_KEY;

@Slf4j
@Component
public class ReservationQuotaExecutor {

    private static final DefaultRedisScript<Long> RESERVATION_SCRIPT;

    static {
        RESERVATION_SCRIPT = new DefaultRedisScript<>();
        RESERVATION_SCRIPT.setLocation(new ClassPathResource("reservation.lua"));
        RESERVATION_SCRIPT.setResultType(Long.class);
    }

    private final StringRedisTemplate stringRedisTemplate;

    public ReservationQuotaExecutor(StringRedisTemplate stringRedisTemplate) {
        this.stringRedisTemplate = stringRedisTemplate;
    }

    /**
     * 调用方已确认窗口开放：now ≤ bookingEndTime ≤ startTime < endTime，因此 Set 的 TTL 恒为正。
     */
    public ReservationResultCode tryAcquire(
            ReservationBatch batch,
            Long userId,
            LocalDateTime now) {
        String quotaKey = RESERVATION_BATCH_QUOTA_KEY + batch.getId();
        String usersKey = RESERVATION_BATCH_USERS_KEY + batch.getId();
        long ttlSeconds = Duration.between(
                now,
                batch.getEndTime().plusHours(RESERVATION_BATCH_QUOTA_TTL_BUFFER_HOURS)).getSeconds();
        Long rawCode = stringRedisTemplate.execute(
                RESERVATION_SCRIPT,
                Arrays.asList(quotaKey, usersKey),
                userId.toString(),
                Long.toString(toEpochSecond(now)),
                Long.toString(toEpochSecond(batch.getBookingStartTime())),
                Long.toString(toEpochSecond(batch.getBookingEndTime())),
                Long.toString(ttlSeconds));
        if (rawCode == null || rawCode < Integer.MIN_VALUE || rawCode > Integer.MAX_VALUE) {
            log.error("预约 Lua 返回异常：{}", rawCode);
            throw new BadRequestException("预约失败，请稍后重试");
        }
        try {
            return ReservationResultCode.fromCode(rawCode.intValue());
        } catch (IllegalArgumentException e) {
            log.error("预约 Lua 返回未知码：{}", rawCode);
            throw new BadRequestException("预约失败，请稍后重试");
        }
    }

    private long toEpochSecond(LocalDateTime time) {
        return time.atZone(ZoneId.systemDefault()).toEpochSecond();
    }
}

package com.yanyuetong.service.impl;

import com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper;
import com.yanyuetong.entity.Reservation;
import com.yanyuetong.entity.ReservationBatch;
import com.yanyuetong.enums.ReservationCancelOutcome;
import com.yanyuetong.enums.ReservationStatus;
import com.yanyuetong.exception.BadRequestException;
import com.yanyuetong.mapper.ReservationBatchMapper;
import com.yanyuetong.mapper.ReservationMapper;
import com.yanyuetong.service.IReservationLifecycleService;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import javax.annotation.Resource;
import java.time.LocalDateTime;

@Slf4j
@Service
public class ReservationLifecycleServiceImpl implements IReservationLifecycleService {

    @Resource
    private ReservationMapper reservationMapper;

    @Resource
    private ReservationBatchMapper reservationBatchMapper;

    @Override
    @Transactional
    public ReservationCancelOutcome cancel(Long reservationId, Long userId, LocalDateTime now) {
        Reservation reservation = reservationMapper.selectById(reservationId);
        if (reservation == null || !userId.equals(reservation.getUserId())) {
            return ReservationCancelOutcome.NOT_FOUND;
        }

        ReservationBatch batch = reservationBatchMapper.selectById(reservation.getBatchId());
        if (batch == null) {
            return ReservationCancelOutcome.NOT_FOUND;
        }
        if (now.isAfter(batch.getEndTime())) {
            throw new BadRequestException("预约已结束，无法取消");
        }

        int transitioned = reservationMapper.update(null,
                new LambdaUpdateWrapper<Reservation>()
                        .eq(Reservation::getId, reservationId)
                        .eq(Reservation::getUserId, userId)
                        .eq(Reservation::getStatus, ReservationStatus.RESERVED)
                        .set(Reservation::getStatus, ReservationStatus.CANCELLED));
        if (transitioned == 0) {
            Reservation current = reservationMapper.selectById(reservationId);
            if (current == null || !userId.equals(current.getUserId())) {
                return ReservationCancelOutcome.NOT_FOUND;
            }
            if (current.getStatus() == ReservationStatus.CANCELLED) {
                return ReservationCancelOutcome.ALREADY_CANCELLED;
            }
            return ReservationCancelOutcome.NOT_CANCELLABLE;
        }

        int quotaRestored = reservationBatchMapper.update(null,
                new LambdaUpdateWrapper<ReservationBatch>()
                        .eq(ReservationBatch::getId, reservation.getBatchId())
                        .lt(ReservationBatch::getRemainingQuota, batch.getTotalQuota())
                        .setSql("remaining_quota = remaining_quota + 1"));
        if (quotaRestored == 0) {
            // MySQL 未回补名额（批次名额已达 totalQuota 上限，或批次行在事务内已变更），
            // 而 Redis 侧仍会 +1。方向保守（不会超卖），但会形成台账偏离，必须留痕以便对账排查。
            log.warn("取消预约后批次名额未回补：reservationId={}，batchId={}，affectedRows=0",
                    reservationId, reservation.getBatchId());
        }
        return ReservationCancelOutcome.TRANSITIONED;
    }

    @Override
    @Transactional
    public boolean complete(Long reservationId, LocalDateTime now) {
        Reservation reservation = reservationMapper.selectById(reservationId);
        if (reservation == null) {
            return false;
        }
        if (reservation.getStatus() == ReservationStatus.COMPLETED) {
            return false;
        }
        if (reservation.getStatus() != ReservationStatus.RESERVED) {
            throw new BadRequestException("当前状态不可核验");
        }

        ReservationBatch batch = reservationBatchMapper.selectById(reservation.getBatchId());
        if (batch == null) {
            return false;
        }
        if (now.isBefore(batch.getStartTime())) {
            throw new BadRequestException("预约尚未开始，无法核验");
        }

        int transitioned = reservationMapper.update(null,
                new LambdaUpdateWrapper<Reservation>()
                        .eq(Reservation::getId, reservationId)
                        .eq(Reservation::getStatus, ReservationStatus.RESERVED)
                        .set(Reservation::getStatus, ReservationStatus.COMPLETED));
        if (transitioned == 1) {
            return true;
        }

        Reservation current = reservationMapper.selectById(reservationId);
        if (current != null && current.getStatus() == ReservationStatus.COMPLETED) {
            return false;
        }
        throw new BadRequestException("当前状态不可核验");
    }
}

package com.yanyuetong.mq;

import com.yanyuetong.config.RabbitMQConfig;
import com.yanyuetong.entity.Reservation;
import com.yanyuetong.entity.ReservationRequest;
import com.yanyuetong.enums.ReservationPersistResult;
import com.yanyuetong.enums.ReservationRequestStatus;
import com.yanyuetong.enums.ReservationStatus;
import com.yanyuetong.service.IReservationPersistenceService;
import com.yanyuetong.service.IReservationRequestService;
import com.yanyuetong.utils.RedisConstants;
import com.rabbitmq.client.Channel;
import lombok.extern.slf4j.Slf4j;
import org.redisson.api.RLock;
import org.redisson.api.RedissonClient;
import org.springframework.amqp.core.Message;
import org.springframework.amqp.rabbit.annotation.RabbitListener;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.messaging.handler.annotation.Payload;
import org.springframework.stereotype.Component;

import javax.annotation.Resource;
import java.io.IOException;
import java.util.concurrent.TimeUnit;

@Slf4j
@Component
public class ReservationMessageConsumer {

    @Resource
    private IReservationPersistenceService reservationPersistenceService;

    @Resource
    private IReservationRequestService reservationRequestService;

    @Resource
    private RedissonClient redissonClient;

    @RabbitListener(queues = RabbitMQConfig.RESERVATION_CREATE_QUEUE)
    public void onReservationMessage(
            @Payload ReservationMessageDTO messageDTO,
            Channel channel,
            Message message) throws IOException {
        long deliveryTag = message.getMessageProperties().getDeliveryTag();
        try {
            ReservationRequest request = reservationRequestService.getByRequestId(
                    messageDTO.getReservationId());
            if (request == null) {
                log.warn("预约请求账本不存在，继续落库：reservationId={}，userId={}",
                        messageDTO.getReservationId(), messageDTO.getUserId());
            } else if (request.getStatus() == ReservationRequestStatus.COMPENSATED) {
                // 该请求已被对账判定终结并归还名额；若此时仍落库，就会形成「MySQL 有行 + Redis 名额已归还」的超发。
                log.warn("预约请求已被补偿，拒绝落库并确认消息：reservationId={}，userId={}",
                        messageDTO.getReservationId(), messageDTO.getUserId());
                channel.basicAck(deliveryTag, false);
                return;
            }

            ReservationPersistResult result = persistWithLock(messageDTO);
            if (result == null) {
                log.error("获取预约锁超时，消息进入死信队列：userId={}，reservationId={}",
                        messageDTO.getUserId(), messageDTO.getReservationId());
                recordFailReasonSafely(messageDTO.getReservationId(), "LOCK_TIMEOUT");
                channel.basicNack(deliveryTag, false, false);
                return;
            }
            switch (result) {
                case PERSISTED:
                case DUPLICATE:
                    markConfirmedSafely(messageDTO.getReservationId());
                    channel.basicAck(deliveryTag, false);
                    break;
                case QUOTA_CONFLICT:
                    recordFailReasonSafely(messageDTO.getReservationId(), "QUOTA_CONFLICT");
                    channel.basicNack(deliveryTag, false, false);
                    break;
                default:
                    throw new IllegalStateException("未知的预约持久化结果：" + result);
            }
        } catch (DuplicateKeyException e) {
            // 同一用户的消息已被 persistWithLock 串行化，此处可达的冲突是 reservationId 主键冲突，不是 uk_user_batch。
            // 若 ACK，这条未落库的消息会静默消失且 DLQ 无痕迹；必须 NACK 交给死信治理。
            log.error("预约记录主键冲突，消息进入死信队列：reservationId={}，userId={}",
                    messageDTO.getReservationId(), messageDTO.getUserId(), e);
            channel.basicNack(deliveryTag, false, false);
        } catch (Exception e) {
            if (e instanceof InterruptedException) {
                Thread.currentThread().interrupt();
            }
            log.error("预约消息处理异常，进入死信队列：reservationId={}",
                    messageDTO.getReservationId(), e);
            recordFailReasonSafely(
                    messageDTO.getReservationId(),
                    "PERSIST_EXCEPTION:" + e.getClass().getSimpleName());
            channel.basicNack(deliveryTag, false, false);
        }
    }

    private void markConfirmedSafely(Long requestId) {
        try {
            boolean confirmed = reservationRequestService.casStatus(
                    requestId,
                    ReservationRequestStatus.CONFIRMED,
                    ReservationRequestStatus.nonTerminalStatuses()
                            .toArray(new ReservationRequestStatus[0]));
            if (!confirmed) {
                log.warn("预约已落库但账本置为 CONFIRMED 未生效：requestId={}", requestId);
            }
        } catch (RuntimeException e) {
            log.error("预约已落库但账本置为 CONFIRMED 异常：requestId={}", requestId, e);
        }
    }

    private void recordFailReasonSafely(Long requestId, String failReason) {
        try {
            boolean recorded = reservationRequestService.recordFailReason(requestId, failReason);
            if (!recorded) {
                log.warn("预约消息失败原因写入未生效：requestId={}，failReason={}",
                        requestId, failReason);
            }
        } catch (RuntimeException e) {
            log.error("预约消息失败原因写入异常：requestId={}，failReason={}",
                    requestId, failReason, e);
        }
    }

    private ReservationPersistResult persistWithLock(ReservationMessageDTO messageDTO)
            throws InterruptedException {
        RLock lock = redissonClient.getLock(
                RedisConstants.LOCK_RESERVATION_KEY + messageDTO.getUserId());
        boolean locked = lock.tryLock(2, 10, TimeUnit.SECONDS);
        if (!locked) {
            return null;
        }
        try {
            Reservation reservation = new Reservation()
                    .setId(messageDTO.getReservationId())
                    .setUserId(messageDTO.getUserId())
                    .setBatchId(messageDTO.getBatchId())
                    .setStatus(ReservationStatus.RESERVED)
                    .setCreateTime(messageDTO.getCreateTime());
            return reservationPersistenceService.persist(reservation);
        } finally {
            if (lock.isHeldByCurrentThread()) {
                lock.unlock();
            }
        }
    }
}

package com.yanyuetong.service.impl;

import com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper;
import com.yanyuetong.dto.ReconcileSummaryDTO;
import com.yanyuetong.entity.Reservation;
import com.yanyuetong.entity.ReservationRequest;
import com.yanyuetong.enums.ReservationRequestStatus;
import com.yanyuetong.mapper.ReservationMapper;
import com.yanyuetong.service.IReservationReconcileService;
import com.yanyuetong.service.IReservationRequestService;
import com.yanyuetong.utils.RedisConstants;
import com.yanyuetong.utils.ReservationQuotaRollbackExecutor;
import lombok.extern.slf4j.Slf4j;
import org.redisson.api.RLock;
import org.redisson.api.RedissonClient;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;

import javax.annotation.Resource;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.concurrent.TimeUnit;

@Slf4j
@Service
public class ReservationReconcileServiceImpl implements IReservationReconcileService {

    private static final String NO_RESERVATION_FAILURE_REASON = "RECONCILE_NO_RESERVATION";
    private static final String RECONCILE_ATTEMPT_FAILED_REASON = "RECONCILE_ATTEMPT_FAILED";
    private static final ReservationRequestStatus[] NON_TERMINAL_STATUSES =
            ReservationRequestStatus.nonTerminalStatuses()
                    .toArray(new ReservationRequestStatus[0]);

    @Resource
    private IReservationRequestService reservationRequestService;

    @Resource
    private ReservationMapper reservationMapper;

    @Resource
    private ReservationQuotaRollbackExecutor rollbackExecutor;

    @Resource
    private RedissonClient redissonClient;

    @Value("${yanyuetong.reservation.reconcile-threshold-ms:600000}")
    private long reconcileThresholdMs;

    @Value("${yanyuetong.reservation.reconcile-limit:200}")
    private int reconcileLimit;

    /**
     * 定时调度薄壳：分布式锁仅减少多实例重复工作，正确性仍由状态 CAS 与幂等补偿保证。
     */
    @Scheduled(
            fixedDelayString = "${yanyuetong.reservation.reconcile-interval-ms:300000}",
            initialDelayString = "${yanyuetong.reservation.reconcile-initial-delay-ms:300000}")
    public void scheduledReconcile() {
        RLock lock = redissonClient.getLock(RedisConstants.LOCK_RESERVATION_RECONCILE_KEY);
        boolean locked;
        try {
            locked = lock.tryLock(0, TimeUnit.MILLISECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new IllegalStateException("预约对账获取分布式锁时被中断", e);
        }
        if (!locked) {
            log.debug("预约对账未获取到分布式锁，跳过本轮");
            return;
        }

        try {
            ReconcileSummaryDTO summary = reconcile(reconcileLimit);
            if (summary.getScanned() == 0) {
                log.debug("预约对账本轮无陈旧请求");
            } else {
                log.info("预约对账完成：scanned={}，confirmed={}，compensated={}，skipped={}，failed={}",
                        summary.getScanned(), summary.getConfirmed(), summary.getCompensated(),
                        summary.getSkipped(), summary.getFailed());
            }
            int released = releasePendingQuotas(reconcileLimit);
            int noShows = markNoShows(reconcileLimit);
            if (released > 0 || noShows > 0) {
                log.info("预约生命周期补偿完成：releasedQuotas={}，noShows={}", released, noShows);
            }
        } finally {
            if (lock.isHeldByCurrentThread()) {
                lock.unlock();
            }
        }
    }

    /**
     * 对账纯方法。每条请求独立处理；单条异常不会回滚或中断本轮其他请求。
     * 已落库分支使用 casStatus，刻意保留 fail_reason 作为最近一次失败的审计线索。
     */
    @Override
    public ReconcileSummaryDTO reconcile(int limit) {
        LocalDateTime before = LocalDateTime.now()
                .minus(reconcileThresholdMs, ChronoUnit.MILLIS);
        List<ReservationRequest> staleRequests = reservationRequestService.listStale(before, limit);

        int confirmed = 0;
        int compensated = 0;
        int skipped = 0;
        int failed = 0;
        for (ReservationRequest request : staleRequests) {
            try {
                if (reservationMapper.selectById(request.getRequestId()) != null) {
                    boolean updated = reservationRequestService.casStatus(
                            request.getRequestId(),
                            ReservationRequestStatus.CONFIRMED,
                            NON_TERMINAL_STATUSES);
                    if (updated) {
                        confirmed++;
                    } else {
                        skipped++;
                    }
                    continue;
                }

                // 必须先补偿再推进终态：补偿失败时保留非终态，下一轮才能继续重试。
                rollbackExecutor.rollback(request.getBatchId(), request.getUserId());
                boolean updated = reservationRequestService.casStatusWithFailReason(
                        request.getRequestId(),
                        ReservationRequestStatus.COMPENSATED,
                        NO_RESERVATION_FAILURE_REASON,
                        NON_TERMINAL_STATUSES);
                if (updated) {
                    compensated++;
                } else {
                    skipped++;
                }
            } catch (Exception e) {
                failed++;
                log.error("预约请求对账失败：requestId={}，batchId={}，userId={}",
                        request.getRequestId(), request.getBatchId(), request.getUserId(), e);
                recordReconcileFailureSafely(request);
            }
        }

        return new ReconcileSummaryDTO(
                staleRequests.size(), confirmed, compensated, skipped, failed);
    }

    /**
     * 重试取消时未成功的 Redis 名额归还。返回本轮完成处理的条数。
     */
    public int releasePendingQuotas(int limit) {
        if (limit <= 0) {
            return 0;
        }
        List<Reservation> pending = reservationMapper.selectPendingQuotaReleases(limit);
        int released = 0;
        for (Reservation reservation : pending) {
            try {
                rollbackExecutor.rollback(reservation.getBatchId(), reservation.getUserId());
                int updated = reservationMapper.update(null,
                        new LambdaUpdateWrapper<Reservation>()
                                .eq(Reservation::getId, reservation.getId())
                                .eq(Reservation::getQuotaReleased, false)
                                .set(Reservation::getQuotaReleased, true));
                if (updated == 1) {
                    released++;
                }
            } catch (Exception e) {
                log.error("取消预约 Redis 名额补偿失败：reservationId={}，batchId={}，userId={}",
                        reservation.getId(), reservation.getBatchId(), reservation.getUserId(), e);
                deferPendingQuotaReleaseSafely(reservation);
            }
        }
        return released;
    }

    private void recordReconcileFailureSafely(ReservationRequest request) {
        try {
            reservationRequestService.recordFailReason(
                    request.getRequestId(), RECONCILE_ATTEMPT_FAILED_REASON);
        } catch (Exception e) {
            log.error("预约请求对账失败原因记录失败：requestId={}", request.getRequestId(), e);
        }
    }

    private void deferPendingQuotaReleaseSafely(Reservation reservation) {
        try {
            reservationMapper.update(null, new LambdaUpdateWrapper<Reservation>()
                    .eq(Reservation::getId, reservation.getId())
                    .set(Reservation::getUpdateTime, LocalDateTime.now()));
        } catch (Exception e) {
            log.error("取消预约 Redis 名额补偿重试时间推进失败：reservationId={}",
                    reservation.getId(), e);
        }
    }

    /**
     * 批次已结束且仍未核验的预约置为爽约。爽约不归还任何名额。
     */
    public int markNoShows(int limit) {
        if (limit <= 0) {
            return 0;
        }
        return reservationMapper.markNoShows(LocalDateTime.now(), limit);
    }
}

package com.yanyuetong.utils;

import cn.hutool.core.util.BooleanUtil;
import cn.hutool.core.util.StrUtil;
import cn.hutool.core.lang.UUID;
import cn.hutool.json.JSONObject;
import cn.hutool.json.JSONUtil;
import lombok.extern.slf4j.Slf4j;
import org.springframework.core.io.ClassPathResource;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.script.DefaultRedisScript;
import org.springframework.stereotype.Component;

import java.time.LocalDateTime;
import java.util.Collections;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.function.Function;

import static com.yanyuetong.utils.RedisConstants.CACHE_NULL_TTL;
import static com.yanyuetong.utils.RedisConstants.LOCK_CACHE_KEY;

/**
 * 缓存查询工具。设备详情正式采用 {@link #queryWithMutex} 的互斥锁重建（方案 A）；
 * {@link #queryWithLogicalExpire} 为未启用的备选实现。
 */
@Slf4j
@Component
public class CacheClient {

    private final StringRedisTemplate stringRedisTemplate;

    private static final ExecutorService CACHE_REBUILD_EXECUTOR = Executors.newFixedThreadPool(10);
    private static final int MUTEX_MAX_RETRY = 20;
    private static final long MUTEX_RETRY_INTERVAL_MS = 50L;
    private static final long MUTEX_LOCK_TTL_SEC = 10L;
    private static final DefaultRedisScript<Long> UNLOCK_SCRIPT;

    static {
        UNLOCK_SCRIPT = new DefaultRedisScript<>();
        UNLOCK_SCRIPT.setLocation(new ClassPathResource("unlock.lua"));
        UNLOCK_SCRIPT.setResultType(Long.class);
    }

    public CacheClient(StringRedisTemplate stringRedisTemplate) {
        this.stringRedisTemplate = stringRedisTemplate;
    }

    public void set(String key, Object value, Long time, TimeUnit unit) {
        stringRedisTemplate.opsForValue().set(key, JSONUtil.toJsonStr(value), time, unit);
    }

    public void setWithLogicalExpire(String key, Object value, Long time, TimeUnit unit) {
        // 设置逻辑过期
        RedisData redisData = new RedisData();
        redisData.setData(value);
        redisData.setExpireTime(LocalDateTime.now().plusSeconds(unit.toSeconds(time)));
        // 写入Redis
        stringRedisTemplate.opsForValue().set(key, JSONUtil.toJsonStr(redisData));
    }

    public <R,ID> R queryWithPassThrough(
            String keyPrefix, ID id, Class<R> type, Function<ID, R> dbFallback, Long time, TimeUnit unit){
        String key = keyPrefix + id;
        // 1.从redis查询缓存
        String json = stringRedisTemplate.opsForValue().get(key);
        // 2.判断是否存在
        if (StrUtil.isNotBlank(json)) {
            // 3.存在，直接返回
            return JSONUtil.toBean(json, type);
        }
        // 判断命中的是否是空值
        if (json != null) {
            // 返回一个错误信息
            return null;
        }

        // 4.不存在，根据id查询数据库
        R r = dbFallback.apply(id);
        // 5.不存在，返回错误
        if (r == null) {
            // 将空值写入redis
            stringRedisTemplate.opsForValue().set(key, "", CACHE_NULL_TTL, TimeUnit.MINUTES);
            // 返回错误信息
            return null;
        }
        // 6.存在，写入redis
        this.set(key, r, time, unit);
        return r;
    }

    public <R, ID> R queryWithLogicalExpire(
            String keyPrefix, ID id, Class<R> type, Function<ID, R> dbFallback, Long time, TimeUnit unit) {
        String key = keyPrefix + id;
        // 1.从redis查询缓存
        String json = stringRedisTemplate.opsForValue().get(key);
        // 2.判断是否存在
        if (StrUtil.isBlank(json)) {
            // 3.存在，直接返回
            return null;
        }
        // 4.命中，需要先把json反序列化为对象
        RedisData redisData = JSONUtil.toBean(json, RedisData.class);
        R r = JSONUtil.toBean((JSONObject) redisData.getData(), type);
        LocalDateTime expireTime = redisData.getExpireTime();
        // 5.判断是否过期
        if(expireTime.isAfter(LocalDateTime.now())) {
            // 5.1.未过期，直接返回数据
            return r;
        }
        // 5.2.已过期，需要缓存重建
        // 6.缓存重建
        // 6.1.获取互斥锁
        String lockKey = LOCK_CACHE_KEY + keyPrefix + id;
        String lockValue = UUID.randomUUID().toString(true);
        boolean isLock = tryLock(lockKey, lockValue);
        // 6.2.判断是否获取锁成功
        if (isLock){
            // 6.3.成功，开启独立线程，实现缓存重建
            CACHE_REBUILD_EXECUTOR.submit(() -> {
                try {
                    // 查询数据库
                    R newR = dbFallback.apply(id);
                    // 重建缓存
                    this.setWithLogicalExpire(key, newR, time, unit);
                } catch (Exception e) {
                    log.error("缓存逻辑过期重建失败, key={}", key, e);
                }finally {
                    // 释放锁
                    unlock(lockKey, lockValue);
                }
            });
        }
        // 6.4.返回过期的数据
        return r;
    }

    public <R, ID> R queryWithMutex(
            String keyPrefix, ID id, Class<R> type, Function<ID, R> dbFallback, Long time, TimeUnit unit) {
        String key = keyPrefix + id;
        String lockKey = LOCK_CACHE_KEY + keyPrefix + id;

        for (int attempt = 0; attempt < MUTEX_MAX_RETRY; attempt++) {
            String json = stringRedisTemplate.opsForValue().get(key);
            if (StrUtil.isNotBlank(json)) {
                return JSONUtil.toBean(json, type);
            }
            if (json != null) {
                return null;
            }

            String lockValue = UUID.randomUUID().toString(true);
            if (!tryLock(lockKey, lockValue)) {
                sleepQuietly(MUTEX_RETRY_INTERVAL_MS);
                continue;
            }

            try {
                String cached = stringRedisTemplate.opsForValue().get(key);
                if (StrUtil.isNotBlank(cached)) {
                    return JSONUtil.toBean(cached, type);
                }
                if (cached != null) {
                    return null;
                }
                R r = dbFallback.apply(id);
                if (r == null) {
                    stringRedisTemplate.opsForValue().set(key, "", CACHE_NULL_TTL, TimeUnit.MINUTES);
                    return null;
                }
                this.set(key, r, time, unit);
                return r;
            } finally {
                unlock(lockKey, lockValue);
            }
        }

        return dbFallback.apply(id);
    }

    private boolean tryLock(String key, String value) {
        Boolean flag = stringRedisTemplate.opsForValue()
                .setIfAbsent(key, value, MUTEX_LOCK_TTL_SEC, TimeUnit.SECONDS);
        return BooleanUtil.isTrue(flag);
    }

    private void unlock(String key, String value) {
        stringRedisTemplate.execute(UNLOCK_SCRIPT, Collections.singletonList(key), value);
    }

    private void sleepQuietly(long millis) {
        try {
            Thread.sleep(millis);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException(e);
        }
    }
}

package com.caiyuntai.utils;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.JwtBuilder;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import java.nio.charset.StandardCharsets;
import java.util.Date;
import java.util.Map;

public class JwtUtil {
    /**
     * 生成jwt
     * 使用Hs256算法, 私匙使用固定秘钥
     *
     * @param secretKey jwt秘钥
     * @param ttlMillis jwt过期时间(毫秒)
     * @param claims    设置的信息
     * @return
     */
    public static String createJWT(String secretKey, long ttlMillis, Map<String, Object> claims) {
        // 指定签名的时候使用的签名算法，也就是header那部分
        SignatureAlgorithm signatureAlgorithm = SignatureAlgorithm.HS256;

        // 生成JWT的时间
        long expMillis = System.currentTimeMillis() + ttlMillis;
        Date exp = new Date(expMillis);

        // 设置jwt的body
        JwtBuilder builder = Jwts.builder()
                // 如果有私有声明，一定要先设置这个自己创建的私有的声明，这个是给builder的claim赋值，一旦写在标准的声明赋值之后，就是覆盖了那些标准的声明的
                .setClaims(claims)
                // 设置签名使用的签名算法和签名使用的秘钥
                .signWith(signatureAlgorithm, secretKey.getBytes(StandardCharsets.UTF_8))
                // 设置过期时间
                .setExpiration(exp);

        return builder.compact();
    }

    /**
     * Token解密
     *
     * @param secretKey jwt秘钥 此秘钥一定要保留好在服务端, 不能暴露出去, 否则sign就可以被伪造, 如果对接多个客户端建议改造成多个
     * @param token     加密后的token
     * @return
     */
    public static Claims parseJWT(String secretKey, String token) {
        // 得到DefaultJwtParser
        Claims claims = Jwts.parser()
                // 设置签名的秘钥
                .setSigningKey(secretKey.getBytes(StandardCharsets.UTF_8))
                // 设置需要解析的jwt
                .parseClaimsJws(token).getBody();
        return claims;
    }

}

package com.caiyuntai.interceptor;

import com.caiyuntai.constant.JwtClaimsConstant;
import com.caiyuntai.constant.RedisKeyConstant;
import com.caiyuntai.constant.StatusConstant;
import com.caiyuntai.context.BaseContext;
import com.caiyuntai.entity.Employee;
import com.caiyuntai.mapper.EmployeeMapper;
import com.caiyuntai.properties.JwtProperties;
import com.caiyuntai.utils.JwtUtil;
import io.jsonwebtoken.Claims;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Component;
import org.springframework.web.method.HandlerMethod;
import org.springframework.web.servlet.HandlerInterceptor;

import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

/**
 * 员工采购端 jwt 令牌校验拦截器
 * <p>
 * 新场景下员工端与管理端共用 employee 表，因此 JWT 的 claims 统一放 empId
 * （原项目用户端使用的 userId 已不再使用）。
 * 两端仍使用不同的密钥与不同的请求头名称，保持隔离。
 */
@Component
@Slf4j
public class JwtTokenUserInterceptor implements HandlerInterceptor {

    @Autowired
    private JwtProperties jwtProperties;
    @Autowired
    private EmployeeMapper employeeMapper;
    @Autowired
    private StringRedisTemplate stringRedisTemplate;

    /**
     * 校验jwt
     *
     * @param request
     * @param response
     * @param handler
     * @return
     * @throws Exception
     */
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) throws Exception {
        //判断当前拦截到的是Controller的方法还是其他资源
        if (!(handler instanceof HandlerMethod)) {
            //当前拦截到的不是动态方法，直接放行
            return true;
        }

        //1、从请求头中获取令牌
        String token = request.getHeader(jwtProperties.getUserTokenName());

        //2、校验令牌
        try {
            log.info("员工端jwt校验:{}", token);
            Claims claims = JwtUtil.parseJWT(jwtProperties.getUserSecretKey(), token);
            Long empId = Long.valueOf(claims.get(JwtClaimsConstant.EMP_ID).toString());
            log.info("当前员工id：{}", empId);

            // 校验 Redis 登录状态：退出登录后旧 token 即使未过期也立即失效
            String loginKey = RedisKeyConstant.LOGIN_TOKEN_PREFIX + token;
            String loginValue = stringRedisTemplate.opsForValue().get(loginKey);
            if (loginValue == null) {
                response.setStatus(401);
                return false;
            }

            //3、写入上下文，供 RoleAspect 与 Mapper 自动填充切面使用
            Employee employee = employeeMapper.getById(empId);
            if (employee == null || StatusConstant.DISABLE.equals(employee.getStatus())) {
                response.setStatus(401);
                return false;
            }

            BaseContext.setCurrentId(empId);
            BaseContext.setCurrentRole(employee.getRole());
            //4、通过，放行
            return true;
        } catch (Exception ex) {
            //5、不通过，响应401状态码
            response.setStatus(401);
            return false;
        }
    }

    /**
     * 请求结束后清理 ThreadLocal，避免线程复用导致的身份串号
     */
    public void afterCompletion(HttpServletRequest request, HttpServletResponse response, Object handler, Exception ex) {
        BaseContext.clear();
    }
}

package com.caiyuntai.aspect;

import com.caiyuntai.annotation.RequireRole;
import com.caiyuntai.constant.MessageConstant;
import com.caiyuntai.context.BaseContext;
import com.caiyuntai.exception.BaseException;
import lombok.extern.slf4j.Slf4j;
import org.aspectj.lang.JoinPoint;
import org.aspectj.lang.annotation.Aspect;
import org.aspectj.lang.annotation.Before;
import org.aspectj.lang.reflect.MethodSignature;
import org.springframework.stereotype.Component;

import java.lang.reflect.Method;
import java.util.Arrays;

/**
 * 角色权限校验切面。
 * <p>
 * 与登录拦截器（JwtTokenAdminInterceptor / JwtTokenUserInterceptor）的分工：
 * - 拦截器负责"有没有登录"，即 JWT 是否合法，并把身份写入 BaseContext；
 * - 本切面负责"登录了能不能做这件事"，即角色是否有权限。
 * <p>
 * 之所以用切面而不是在拦截器里判断，是因为拦截器只能拿到 HandlerMethod 的类型信息，
 * 而注解的读取与方法级覆盖（类上标注、方法上覆盖）用反射处理更自然，
 * 也和项目里 AutoFillAspect 的"自定义注解 + 切面"模式保持一致。
 */
@Aspect
@Component
@Slf4j
public class RoleAspect {

    @Before("@annotation(com.caiyuntai.annotation.RequireRole) || @within(com.caiyuntai.annotation.RequireRole)")
    public void checkRole(JoinPoint joinPoint) {
        MethodSignature signature = (MethodSignature) joinPoint.getSignature();
        Method method = signature.getMethod();

        // 方法上的注解优先，没有再看类上的
        RequireRole requireRole = method.getAnnotation(RequireRole.class);
        if (requireRole == null) {
            requireRole = method.getDeclaringClass().getAnnotation(RequireRole.class);
        }
        if (requireRole == null) {
            return;
        }

        String[] allowed = requireRole.value();
        if (allowed.length == 0) {
            return;
        }

        String currentRole = BaseContext.getCurrentRole();
        if (currentRole == null) {
            // 没有角色信息，说明请求没有经过登录拦截器，按未登录处理
            log.warn("角色校验失败：未获取到登录角色，方法={}", method.getName());
            throw new BaseException(MessageConstant.USER_NOT_LOGIN);
        }

        boolean pass = Arrays.stream(allowed).anyMatch(role -> role.equals(currentRole));
        if (!pass) {
            log.warn("角色校验失败：当前角色={}，允许角色={}，方法={}",
                    currentRole, Arrays.toString(allowed), method.getName());
            throw new BaseException(MessageConstant.NO_PERMISSION);
        }
    }

}

package com.caiyuntai.service.impl;

import com.caiyuntai.constant.MessageConstant;
import com.caiyuntai.constant.StatusConstant;
import com.caiyuntai.dto.BudgetDTO;
import com.caiyuntai.entity.Budget;
import com.caiyuntai.exception.BaseException;
import com.caiyuntai.mapper.BudgetMapper;
import com.caiyuntai.service.BudgetService;
import com.caiyuntai.vo.BudgetVO;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.List;

@Service
@Slf4j
public class BudgetServiceImpl implements BudgetService {

    private static final DateTimeFormatter PERIOD_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM");

    @Autowired
    private BudgetMapper budgetMapper;

    /**
     * 设置部门预算
     *
     * @param budgetDTO
     */
    public void save(BudgetDTO budgetDTO) {
        // 同一部门同一周期只允许一条预算记录
        Budget exist = budgetMapper.getByDeptAndPeriod(budgetDTO.getDeptId(), budgetDTO.getPeriod());
        if (exist != null) {
            throw new BaseException("该部门在该周期的预算已存在，请直接修改");
        }

        Budget budget = Budget.builder()
                .deptId(budgetDTO.getDeptId())
                .period(budgetDTO.getPeriod() == null ? currentPeriod() : budgetDTO.getPeriod())
                .totalAmount(budgetDTO.getTotalAmount() == null ? BigDecimal.ZERO : budgetDTO.getTotalAmount())
                .usedAmount(BigDecimal.ZERO)
                .status(budgetDTO.getStatus() == null ? StatusConstant.ENABLE : budgetDTO.getStatus())
                .build();

        budgetMapper.insert(budget);
    }

    /**
     * 修改预算
     *
     * @param budgetDTO
     */
    public void update(BudgetDTO budgetDTO) {
        Budget budget = Budget.builder()
                .id(budgetDTO.getId())
                .deptId(budgetDTO.getDeptId())
                .period(budgetDTO.getPeriod())
                .totalAmount(budgetDTO.getTotalAmount())
                .status(budgetDTO.getStatus())
                .build();

        budgetMapper.update(budget);
    }

    public List<BudgetVO> list(Budget budget) {
        return budgetMapper.list(budget);
    }

    public BudgetVO getVOByDeptAndPeriod(Long deptId, String period) {
        Budget budget = budgetMapper.getByDeptAndPeriod(deptId, period);
        if (budget == null) {
            return null;
        }
        return budgetMapper.getVOById(budget.getId());
    }

    /**
     * 预扣预算
     * deduct 内部是带条件的原子 UPDATE，影响行数为 0 即表示扣减失败。
     *
     * @param deptId
     * @param period
     * @param amount
     * @return
     */
    public boolean deduct(Long deptId, String period, BigDecimal amount) {
        if (deptId == null || amount == null || amount.signum() <= 0) {
            return false;
        }
        int rows = budgetMapper.deduct(deptId, period, amount);
        if (rows == 0) {
            log.warn("预算预扣失败：deptId={}, period={}, amount={}", deptId, period, amount);
            return false;
        }
        return true;
    }

    /**
     * 返还预算
     *
     * @param deptId
     * @param period
     * @param amount
     * @return
     */
    public boolean release(Long deptId, String period, BigDecimal amount) {
        if (deptId == null || amount == null) {
            return false;
        }
        int rows = budgetMapper.release(deptId, period, amount);
        if (rows == 0) {
            log.warn("预算返还失败（可能已返还过）：deptId={}, period={}, amount={}", deptId, period, amount);
            return false;
        }
        return true;
    }

    public String currentPeriod() {
        return LocalDateTime.now().format(PERIOD_FORMATTER);
    }

    public String periodOf(LocalDateTime dateTime) {
        LocalDateTime time = dateTime == null ? LocalDateTime.now() : dateTime;
        return time.format(PERIOD_FORMATTER);
    }

}

package com.caiyuntai.controller.user;

import com.caiyuntai.constant.RedisKeyConstant;
import com.caiyuntai.constant.StatusConstant;
import com.caiyuntai.entity.Combo;
import com.caiyuntai.result.Result;
import com.caiyuntai.service.ComboService;
import com.caiyuntai.vo.GoodsItemVO;
import io.swagger.annotations.Api;
import io.swagger.annotations.ApiOperation;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;

@RestController("userComboController")
@RequestMapping("/user/combo")
@Api(tags = "C端-组合申领包浏览接口")
public class ComboController {
    @Autowired
    private ComboService comboService;

    @Autowired
    private RedisTemplate redisTemplate;

    /**
     * 条件查询
     * <p>
     * @param categoryId
     * @return
     */
    @GetMapping("/list")
    @ApiOperation("根据物资分类id查询组合申领包")
    public Result<List<Combo>> list(Long categoryId) {
        // Cache-Aside：无分类时归一为 'all'，key 形如 combo:list:27 / combo:list:all
        String key = RedisKeyConstant.COMBO_LIST_PREFIX + (categoryId == null ? "all" : categoryId);
        List<Combo> list = (List<Combo>) redisTemplate.opsForValue().get(key);
        if (list != null) {
            return Result.success(list);
        }

        Combo combo = new Combo();
        combo.setCategoryId(categoryId);
        combo.setStatus(StatusConstant.ENABLE);
        list = comboService.list(combo);

        if (list == null) {
            list = new ArrayList<>();
        }
        // 空结果短 TTL 防穿透；正常结果 30 分钟 + 随机抖动避免集中失效
        long ttl = list.isEmpty() ? 60 : (30 * 60 + ThreadLocalRandom.current().nextInt(300));
        redisTemplate.opsForValue().set(key, list, ttl, TimeUnit.SECONDS);

        return Result.success(list);
    }

    /**
     * 根据组合申领包id查询包含的物资列表
     *
     * @param id
     * @return
     */
    @GetMapping("/goods/{id}")
    @ApiOperation("根据组合申领包id查询包含的物资列表")
    public Result<List<GoodsItemVO>> goodsList(@PathVariable("id") Long id) {
        List<GoodsItemVO> list = comboService.getGoodsItemById(id);
        return Result.success(list);
    }
}
